join public.scientific_import_batches as batch
  on batch.batch_key = 'CORE-v2.3-AUDITADO__APP-SCIENTIFIC-MVP-v2'
join public.edicts as edict
  on edict.source_process_id = item.source_process_id
on conflict do nothing;

update public.scientific_import_batches
set
    status = 'APPLIED',
    counts = '{"source_processes":221,"imported_edicts":220,"excluded_processes":1,"institutions":398,"links":462,"indexers":15,"scientific_rules":197,"scientific_rules_published":167,"scientific_rules_blocked":30,"mapped_processes":40,"source_pending_issues":42,"journals":0}'::jsonb,
    completed_at = now()
where batch_key = 'CORE-v2.3-AUDITADO__APP-SCIENTIFIC-MVP-v2';

do $$
declare
    imported_institutions integer;
    imported_edicts integer;
    imported_links integer;
    imported_indexers integer;
    imported_rules integer;
    published_rules integer;
begin
    select count(*) into imported_institutions
    from public.institutions
    where source_institution_id is not null;

    select count(*) into imported_edicts
    from public.edicts
    where source_process_id is not null;

    select count(*) into imported_links
    from public.edict_institutions;

    select count(*) into imported_indexers
    from public.indexers
    where code is not null;

    select count(*) into imported_rules
    from public.scientific_rules
    where release_code = 'APP-SCIENTIFIC-MVP-v2';

    select count(*) into published_rules
    from public.scientific_rules
    where release_code = 'APP-SCIENTIFIC-MVP-v2'
      and published_for_engine;

    if imported_institutions <> 398
       or imported_edicts <> 220
       or imported_links <> 462
       or imported_indexers <> 15
       or imported_rules <> 197
       or published_rules <> 167 then
        raise exception 'CORE_V2_3_IMPORT_RECONCILIATION_FAILED institutions=% edicts=% links=% indexers=% rules=% published=%',
            imported_institutions,
            imported_edicts,
            imported_links,
            imported_indexers,
            imported_rules,
            published_rules;
    end if;
end;
$$;
